) VALUES
('astrotooblack', 'astrotoo', 'Astrotoo Black', 'Speaker Bluetooth desktop 20W dengan layar visual 3,95 inci beresolusi 480×480, kontrol fisik, dan pengaturan melalui aplikasi.', '<p>Divoom Astrotoo adalah speaker desktop dan layar pintar yang menggabungkan audio 20W dengan layar 3,95 inci beresolusi 480×480. Dirancang untuk mendengarkan musik di meja kerja, bermain game, dan menampilkan konten visual yang dapat dipersonalisasi.</p><ul><li>Menampilkan pixel art, foto, tampilan jam, dan visual musik.</li><li>Tombol fisik dan joystick untuk kontrol langsung.</li><li>Pemutaran melalui Bluetooth 6.0, Wi-Fi, dan MicroSD.</li><li>Daya tahan baterai hingga 6 jam menurut informasi Divoom.</li><li>Tersedia dalam varian White, Black, dan Pink pada katalog produk.</li></ul>', 'in stock', 'new', 3627819, NULL, '/products/astrotoo', 'https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/astrotooblack/main_fe036892-4cb0-4cba-9fa1-249d0a25ff5e.jpg', '[]'::jsonb, 'Divoom', '597', 'Display', 'Black', NULL, NULL, NULL, NULL, NULL, NULL),
('astrotoopink', 'astrotoo', 'Astrotoo Pink', 'Speaker Bluetooth desktop 20W dengan layar visual 3,95 inci beresolusi 480×480, kontrol fisik, dan pengaturan melalui aplikasi.', '<p>Divoom Astrotoo adalah speaker desktop dan layar pintar yang menggabungkan audio 20W dengan layar 3,95 inci beresolusi 480×480. Dirancang untuk mendengarkan musik di meja kerja, bermain game, dan menampilkan konten visual yang dapat dipersonalisasi.</p><ul><li>Menampilkan pixel art, foto, tampilan jam, dan visual musik.</li><li>Tombol fisik dan joystick untuk kontrol langsung.</li><li>Pemutaran melalui Bluetooth 6.0, Wi-Fi, dan MicroSD.</li><li>Daya tahan baterai hingga 6 jam menurut informasi Divoom.</li><li>Tersedia dalam varian White, Black, dan Pink pada katalog produk.</li></ul>', 'in stock', 'new', 3627819, NULL, '/products/astrotoo', 'https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/astrotoopink/main_f7374347-4e88-4125-9a10-527fed096095.jpg', '[]'::jsonb, 'Divoom', '597', 'Display', 'Pink', NULL, NULL, NULL, NULL, NULL, NULL),
('astrotoowhite', 'astrotoo', 'Astrotoo White', 'Speaker Bluetooth desktop 20W dengan layar visual 3,95 inci beresolusi 480×480, kontrol fisik, dan pengaturan melalui aplikasi.', '<p>Divoom Astrotoo adalah speaker desktop dan layar pintar yang menggabungkan audio 20W dengan layar 3,95 inci beresolusi 480×480. Dirancang untuk mendengarkan musik di meja kerja, bermain game, dan menampilkan konten visual yang dapat dipersonalisasi.</p><ul><li>Menampilkan pixel art, foto, tampilan jam, dan visual musik.</li><li>Tombol fisik dan joystick untuk kontrol langsung.</li><li>Pemutaran melalui Bluetooth 6.0, Wi-Fi, dan MicroSD.</li><li>Daya tahan baterai hingga 6 jam menurut informasi Divoom.</li><li>Tersedia dalam varian White, Black, dan Pink pada katalog produk.</li></ul>', 'in stock', 'new', 3627819, NULL, '/products/astrotoo', 'https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/astrotoowhite/main_03521c4f-5404-4caf-83a9-3154fd432b8b.jpg', '[]'::jsonb, 'Divoom', '597', 'Display', 'White', NULL, NULL, NULL, NULL, NULL, NULL),
('backpacks', 'backpacks', 'Backpack-S', 'Tas ransel untuk penggunaan sehari-hari dengan layar LED piksel yang dapat dikendalikan melalui aplikasi untuk menampilkan animasi, ikon, dan pesan sesuai keinginan.', '<p>Divoom Backpack-S adalah tas ransel sehari-hari dengan layar LED bawaan yang dapat menampilkan animasi, ikon, dan pesan khusus. Tampilan layar dapat dipersonalisasi melalui aplikasi Divoom.</p><ul><li>Dirancang untuk sekolah, perjalanan harian, bepergian, dan aktivitas santai.</li><li>Panel belakang berlapis bantalan dan struktur tas yang diperkuat.</li><li>Saku samping untuk akses cepat ke kebutuhan sehari-hari.</li><li>Berat produk sekitar 730g.</li></ul>', 'in stock', 'new', 2720819, NULL, '/products/backpacks', 'https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/backpacks/main_9b82e261-1156-4748-bcf5-fad09e3835cf.jpg', '["https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/backpacks/additional_6e39c8ad-b875-43e9-831c-86a564ec552c.jpg","https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/backpacks/additional_7afc024e-1ca1-4fe3-95fd-3250473dc325.jpg","https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/backpacks/additional_5d22a782-4468-4e6f-8c6b-6a6761c9ad61.jpg"]'::jsonb, 'Divoom', '100', 'Backpack', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('cyberbag', 'cyberbag', 'Cyberbag', 'Tas ransel LED pintar bergaya cyberpunk dengan layar 64×64 piksel, kompartemen penyimpanan yang tertata, dan ruang untuk laptop hingga 15 inci.', '<p>Divoom Cyberbag adalah tas ransel LED pintar dengan layar 64×64 piksel untuk menampilkan karya visual, logo, dan animasi khusus. Desain terinspirasi cyberpunk ini memadukan tampilan piksel yang dapat dikenakan dengan ruang penyimpanan praktis untuk perjalanan harian dan bepergian.</p><ul><li>Layar LED 64×64 yang dikendalikan melalui aplikasi.</li><li>Tata ruang dengan bukaan penuh, saku tersembunyi untuk barang berharga, dan kompartemen laptop hingga 15 inci.</li><li>Konstruksi ABS, PC, dan poliester dengan kain tahan air.</li><li>Tali bahu yang dapat disesuaikan dan panel belakang mesh berlapis bantalan.</li></ul>', 'in stock', 'new', 3627819, NULL, '/products/cyberbag', 'https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/cyberbag/main_f740fe38-2f53-4c88-89c7-b179e38aa902.jpg', '["https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/cyberbag/additional_c38a446e-d931-48f0-8174-f05d592c4c54.jpg","https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/cyberbag/additional_2f0ccc06-dae8-459d-9d9d-d134bd502c2b.jpg","https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/cyberbag/additional_2afabca0-2344-488e-b54f-e5c98e5724d3.jpg"]'::jsonb, 'Divoom', '100', 'Backpack', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('ditoo5micblue', 'ditoo5mic', 'Ditoo 5-Mic Blue', 'Speaker karaoke Bluetooth 15W bergaya retro dengan layar LED piksel, keyboard mekanis RGB, dan mikrofon nirkabel mini.', '<p>Divoom Ditoo 5-Mic adalah speaker karaoke Bluetooth bergaya komputer retro yang memadukan layar LED pixel art, keyboard mekanis RGB, dan mikrofon mini nirkabel.</p><ul><li>Speaker 15W dengan driver 48mm 19-core dan dua radiator pasif.</li><li>Membuat pixel art dan animasi, menampilkan tampilan jam, serta menggunakan fitur piksel melalui aplikasi Divoom.</li><li>Dirancang untuk karaoke di rumah, kumpul keluarga, meja kerja, dan ruang bermain game.</li><li>Tersedia dalam warna Pink, Blue, dan Green.</li></ul>', 'in stock', 'new', 2539419, NULL, '/products/ditoo5mic', 'https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/ditoo5micblue/main_800f3735-417b-456e-96c0-440d6434920d.jpg', '[]'::jsonb, 'Divoom', '249', 'Speakers', 'Blue', NULL, NULL, NULL, NULL, NULL, NULL),
