('timesframepure', 'timesframepure', 'Times Frame Pure', 'Bingkai foto digital mengambang dengan layar optik tiga lapis, penyimpanan 32GB, dan fitur berbagi jarak jauh melalui Wi-Fi 6.', '<p>Divoom Times Frame Pure adalah bingkai foto digital dengan efek visual melayang melalui struktur optik tiga lapis yang menggabungkan kaca tempered, LCD transparan, dan pelat belakang pemandu cahaya nano untuk menghasilkan kedalaman visual.</p><ul><li>Penyimpanan 32GB untuk foto dan video.</li><li>Berbagi foto, video, dan pesan jarak jauh melalui Wi-Fi 6.</li><li>Lebih dari 50 aplikasi dan 400+ tampilan jam dinamis, serta fitur cuaca, saham, kalender, dan catatan.</li><li>Dikendalikan melalui aplikasi Divoom atau kenop putar bawaan.</li></ul>', 'in stock', 'new', 2902219, NULL, '/products/timesframepure', 'https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/timesframepure/main_f99886fb-eb9f-46d5-9e08-9ff5703ae82f.jpg', '["https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/timesframepure/additional_829ca0aa-aee7-46f1-9826-d43793dc3ec9.jpg","https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/timesframepure/additional_3af2ddd4-16b3-484e-93c3-af38b2fc8777.jpg","https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/timesframepure/additional_a75e9f2d-4957-47d3-b321-63ccef7633a1.jpg","https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/timesframepure/additional_8f618153-8a43-44be-8d85-22df74f2ee60.jpg","https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/timesframepure/additional_dc5dd9ff-7bf6-429c-8518-bddedf477959.jpg"]'::jsonb, 'Divoom', '597', 'Display', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('timesgateblack', 'timesgate', 'Times Gate Black', 'Layar informasi desktop dengan lima layar LCD berwarna penuh beresolusi 128×128, widget langsung, dan pencahayaan RGB yang dapat dikustomisasi.', '<p>Divoom Times Gate adalah layar informasi pixel art multi-layar dengan lima panel LCD full-color 128×128. Perangkat ini menggabungkan jam, data langsung, dan visual khusus dalam satu dasbor desktop.</p><ul><li>Menampilkan cuaca, jam dunia, acara kalender, data saham, serta penghitung media sosial atau kreator yang didukung.</li><li>Menyesuaikan setiap layar dengan pixel art, animasi, GIF, dan widget melalui aplikasi Divoom.</li><li>Pencahayaan ambient di kedua sisi dengan 12 efek RGB.</li><li>Menggunakan Wi-Fi 2,4GHz dan memerlukan daya tersambung terus-menerus.</li></ul>', 'in stock', 'new', 2539419, NULL, '/products/timesgate', 'https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/timesgateblack/main_61ef31ab-b7d9-4c7b-ae61-e41d60ab4215.jpg', '["https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/timesgateblack/additional_e6f1574e-fec5-4279-86a0-26e2dc8f6567.jpg","https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/timesgateblack/additional_f083118d-e87c-4f17-8ae0-999c622ff7a2.jpg","https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/timesgateblack/additional_30808b9d-7f92-4889-bdb1-83f417402f74.jpg","https://mvwflakurihhakdrlteg.supabase.co/storage/v1/object/public/divoom-product-images/timesgateblack/additional_70a9a9ee-4cb7-4644-a3f7-e3fda1653791.jpg"]'::jsonb, 'Divoom', '597', 'Display', 'Black', NULL, NULL, NULL, NULL, NULL, NULL),
